(async()=>{
const VERSION='v1-author-export';
const PANEL_ID='automa-author-export-v1-panel';
const pageLength=140;
const maxPages=48;
const waitMs=350;
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const log=(stage,extra={})=>console.info('[AUTOMA-SCRIPT]',{workflow:'kiwix-author-export',version:VERSION,stage,...extra});
if(!document.body){automaNextBlock();return;}
let panel=document.getElementById(PANEL_ID);
if(!panel){panel=document.createElement('div');panel.id=PANEL_ID;Object.assign(panel.style,{position:'fixed',right:'20px',top:'20px',zIndex:'2147483647',minWidth:'300px',maxWidth:'440px',padding:'12px 16px',background:'#fff',color:'#222',border:'1px solid #888',borderRadius:'8px',boxShadow:'0 3px 16px rgba(0,0,0,.25)',font:'14px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif'});document.body.appendChild(panel)}
const update=(text,ok=false)=>{panel.textContent=text;panel.style.borderColor=ok?'#248a3d':'#888'};
try{
 const current=new URL(location.href);
 let searchUrl=null;
 let source='search';
 if(current.pathname.endsWith('/search')){
  searchUrl=current;
 }else if(current.pathname.endsWith('/viewer')){
  source='viewer-web';
  const iframe=document.querySelector('#content_iframe,iframe[src*="/search"]');
  const iframeSrc=iframe?.getAttribute('src')||'';
  if(!iframeSrc)throw Error('Viewer 页面尚未载入搜索 iframe');
  searchUrl=new URL(iframeSrc,current.href);
 }else throw Error('当前页面不是 Kiwix /search 或 /viewer 页面');
 const pattern=searchUrl.searchParams.get('pattern')||'Author';
 const book=searchUrl.searchParams.get('books.name');
 if(!book)throw Error('当前搜索 iframe URL 缺少 books.name');
 const baseUrl=new URL(searchUrl.href);baseUrl.pathname='/search';baseUrl.hash='';baseUrl.search='';
 const records=[];const seen=new Set();const failed=[];let total=0;
 const parsePage=(html)=>{const doc=new DOMParser().parseFromString(html,'text/html');const root=doc.querySelector('.results');if(!root)return{items:[],total:0};const heading=(root.querySelector('h1,h2')||doc.querySelector('h1,h2'))?.textContent||'';const match=heading.match(/of\s+([\d,]+)/i);const pageTotal=match?Number(match[1].replace(/,/g,'')):0;const items=[];for(const li of root.querySelectorAll('li')){const a=li.querySelector('a[href]');if(!a)continue;const url=new URL(a.getAttribute('href'),baseUrl.origin).href;const title=a.textContent.trim();if(!title||seen.has(url))continue;seen.add(url);items.push({title,url,info:li.textContent.replace(/\s+/g,' ').trim()})}return{items,total:pageTotal||0}};
 for(let page=0;page<maxPages;page++){
  const start=page*pageLength;update(`正在查询 Author：第 ${page+1}/${maxPages} 页，已收集 ${records.length} 条（${source}）`);
  let parsed=null,lastError='';
  for(let attempt=0;attempt<3;attempt++){try{const u=new URL(baseUrl.href);u.searchParams.set('pattern',pattern);u.searchParams.set('books.name',book);u.searchParams.set('start',String(start));u.searchParams.set('pageLength',String(pageLength));const response=await fetch(u.href,{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw Error(`HTTP ${response.status}`);parsed=parsePage(await response.text());break}catch(e){lastError=String(e);await sleep(600)}}
  if(!parsed){failed.push({start,error:lastError});continue}
  total=Math.max(total,parsed.total);records.push(...parsed.items);
  if(!parsed.items.length||(total&&records.length>=total))break;
  await sleep(waitMs);
 }
 const lines=['Kiwix Author 全量导出','source: '+source,'pattern: '+pattern,'book: '+book,'pageLength: '+pageLength,'records: '+records.length,'failedPages: '+failed.length,''];
 records.forEach((r,i)=>{lines.push(`[${String(i+1).padStart(6,'0')}]`,'标题：'+r.title,'URL：'+r.url,'信息：'+r.info,'')});
 if(failed.length)lines.push('失败页：'+failed.map(x=>x.start).join(', '));
 const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');const blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/plain;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`kiwix-author-${stamp}.txt`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),60000);
 update(`导出完成：${records.length} 条，${Math.min(maxPages,Math.ceil((records.length||1)/pageLength))} 页，失败 ${failed.length} 页`,true);log('complete',{records:records.length,total,failed:failed.length,source,book});
}catch(e){update('导出失败：'+String(e).slice(0,180));console.error('[AUTOMA-SCRIPT-ERROR]',String(e).slice(0,240))}
automaNextBlock();
})().catch(e=>{console.error('[AUTOMA-SCRIPT-ERROR]',String(e).slice(0,240));automaNextBlock()});
